// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address admin, string calldata description) public {
        vm.assume(admin != address(0));
        vm.prank(admin);
        c.newEmergencyOracle(description);
        // After calling newEmergencyOracle as admin, the owner of the new EmergencyOracle must equal the caller (admin).
        // The buggy version passes address(0) as owner, so the ownership will be address(0) instead of the caller.
        assertTrue(c.owner() == admin);
    }
}
